  app.get("/api/provider-search", requireAuth, async (req: Request, res: Response) => {
    try {
      const { q, state, specialty, org } = req.query as any;
      const searchName = (q as string || "").trim();
      const searchOrg = (org as string || "").trim();
      if (searchName.length < 2 && searchOrg.length < 2) {
        return res.json({ results: [] });
      }

      const fetchResults = async (searchParams: URLSearchParams) => {
        const npiUrl = `https://npiregistry.cms.hhs.gov/api/?${searchParams.toString()}`;
        const response = await fetch(npiUrl);
        if (!response.ok) return [];
        const data = await response.json() as any;
        return (data.results || []).map((r: any) => {
          const basic = r.basic || {};
          const addr = (r.addresses || []).find((a: any) => a.address_purpose === "LOCATION") || (r.addresses || [])[0] || {};
          const taxonomy = (r.taxonomies || []).find((t: any) => t.primary) || (r.taxonomies || [])[0] || {};
          return {
            npi: r.number,
            firstName: basic.first_name || basic.organization_name || "",
            lastName: basic.last_name || "",
            credential: basic.credential || "",
            specialty: taxonomy.desc || "",
            phone: addr.telephone_number || "",
            city: addr.city || "",
            state: addr.state || "",
            address: [addr.address_1, addr.city, addr.state, addr.postal_code].filter(Boolean).join(", "),
            organizationName: basic.organization_name || "",
          };
        });
      };

      const searches: Promise<any[]>[] = [];

      if (searchName.length >= 2) {
        const nameParams = new URLSearchParams();
        nameParams.set("version", "2.1");
        nameParams.set("limit", "15");
        nameParams.set("enumeration_type", "NPI-1");
        const nameParts = searchName.split(/\s+/);
        if (nameParts.length >= 2) {
          nameParams.set("first_name", nameParts[0] + "*");
          nameParams.set("last_name", nameParts.slice(1).join(" ") + "*");
        } else {
          nameParams.set("last_name", searchName + "*");
        }
        if (state) nameParams.set("state", state as string);
        if (specialty) nameParams.set("taxonomy_description", specialty as string + "*");
        searches.push(fetchResults(nameParams));
      }

      if (searchOrg.length >= 2 || searchName.length >= 2) {
        const orgParams = new URLSearchParams();
        orgParams.set("version", "2.1");
        orgParams.set("limit", "10");
        orgParams.set("enumeration_type", "NPI-2");
        orgParams.set("organization_name", (searchOrg || searchName) + "*");
        if (state) orgParams.set("state", state as string);
        searches.push(fetchResults(orgParams));
      }

      const allResults = await Promise.all(searches);
      const combined = allResults.flat();
      const seen = new Set<string>();
      const deduplicated = combined.filter(r => {
        if (seen.has(r.npi)) return false;
        seen.add(r.npi);
        return true;
      });

      res.json({ results: deduplicated.slice(0, 20) });
    } catch (error) {
      console.error("Provider search error:", error);
      res.json({ results: [] });
    }
  });


  app.get("/api/pharmacy-search", requireAuth, async (req: Request, res: Response) => {
    try {
      const { q, zip } = req.query as any;
      const searchName = (q as string || "").trim();
      const searchZip = (zip as string || "").trim();
      if (searchName.length < 2 && searchZip.length < 3) {
        return res.json({ results: [] });
      }

      const params = new URLSearchParams();
      params.set("version", "2.1");
      params.set("limit", "20");
      params.set("enumeration_type", "NPI-2");
      params.set("taxonomy_description", "Pharmacy*");

      if (searchName.length >= 2) {
        params.set("organization_name", searchName + "*");
      }
      if (searchZip.length >= 3) {
        params.set("postal_code", searchZip + "*");
      }

      const npiUrl = `https://npiregistry.cms.hhs.gov/api/?${params.toString()}`;
      const response = await fetch(npiUrl);

      if (!response.ok) {
        return res.json({ results: [] });
      }

      const data = await response.json() as any;
      const results = (data.results || []).map((r: any) => {
        const basic = r.basic || {};
        const addr = (r.addresses || []).find((a: any) => a.address_purpose === "LOCATION") || (r.addresses || [])[0] || {};
        return {
          npi: r.number,
          name: basic.organization_name || "",
          phone: addr.telephone_number || "",
          fax: addr.fax_number || "",
          address: [addr.address_1, addr.city, addr.state, addr.postal_code].filter(Boolean).join(", "),
          city: addr.city || "",
          state: addr.state || "",
          zip: addr.postal_code || "",
        };
      });

      res.json({ results });
    } catch (error) {
      console.error("Pharmacy search error:", error);
      res.json({ results: [] });
    }
  });


  app.get("/api/provider-share-summary", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const profile = await storage.getPatientProfile(userId);
      const records = await storage.getHealthRecords(userId);

      const conditions: any[] = [];
      const surgeries: any[] = [];
      const familyHistory: any[] = [];
      const medications: any[] = [];
      const allergies: any[] = [];
      const pertinentPositives: string[] = [];

      for (const r of records) {
        const isManual = r.isManual || false;
        const source = isManual ? "patient" : "ehr";
        if (r.type === "condition") {
          const item = { category: "condition", name: r.title, detail: r.summary || "", source, highlighted: false, clinicalNote: "" };
          const lower = (r.title || "").toLowerCase();
          if (["hypertension", "diabetes", "coronary", "heart disease", "copd", "cancer", "stroke", "ckd", "chronic kidney"].some(k => lower.includes(k))) {
            item.highlighted = true;
            pertinentPositives.push(`${r.title}${r.summary ? ` (${r.summary})` : ""}`);
          }
          conditions.push(item);
        } else if (r.type === "procedure") {
          const item = { category: "surgery", name: r.title, detail: r.summary || "", source, highlighted: false };
          const lower = (r.title || "").toLowerCase();
          if (["bypass", "stent", "pacemaker", "mastectomy", "replacement"].some(k => lower.includes(k))) {
            item.highlighted = true;
            pertinentPositives.push(`Surgical: ${r.title}`);
          }
          surgeries.push(item);
        } else if (r.type === "medication") {
          const item = { category: "medication", name: r.title, detail: r.summary || "", source, highlighted: false };
          const lower = (r.title || "").toLowerCase();
          if (["warfarin", "insulin", "metformin", "statin", "anticoagulant", "blood thinner"].some(k => lower.includes(k))) {
            item.highlighted = true;
          }
          medications.push(item);
        } else if (r.type === "allergy") {
          allergies.push({ category: "allergy", name: r.title, detail: r.summary || "", source, highlighted: true });
          pertinentPositives.push(`Allergy: ${r.title}`);
        }
      }

      const healthConditions = (profile as any)?.healthConditions;
      if (Array.isArray(healthConditions)) {
        for (const c of healthConditions) {
          const name = typeof c === "string" ? c : c.name || "";
          if (name && !conditions.find(x => x.name.toLowerCase() === name.toLowerCase())) {
            const lower = name.toLowerCase();
            const highlighted = ["hypertension", "diabetes", "coronary", "heart", "copd", "cancer", "stroke", "kidney"].some(k => lower.includes(k));
            conditions.push({ category: "condition", name, detail: "", source: "patient", highlighted });
            if (highlighted) pertinentPositives.push(name);
          }
        }
      }

      const profileSurgeries = (profile as any)?.surgeries;
      if (Array.isArray(profileSurgeries)) {
        for (const s of profileSurgeries) {
          const name = typeof s === "string" ? s : s.name || "";
          if (name && !surgeries.find(x => x.name.toLowerCase() === name.toLowerCase())) {
            surgeries.push({ category: "surgery", name, detail: "", source: "patient", highlighted: false });
          }
        }
      }

      const profileFamily = (profile as any)?.familyHistory;
      if (Array.isArray(profileFamily)) {
        for (const f of profileFamily) {
          const text = typeof f === "string" ? f : `${f.condition || ""}${f.relation ? ` (${f.relation})` : ""}`;
          if (text.trim()) {
            const lower = text.toLowerCase();
            const highlighted = ["cancer", "heart", "diabetes", "stroke", "clot", "sickle"].some(k => lower.includes(k));
            familyHistory.push({ category: "family", name: text, detail: "", source: "patient", highlighted });
            if (highlighted) pertinentPositives.push(`Family: ${text}`);
          }
        }
      }

      const lastReviewStr = (profile as any)?.lastHealthReviewDate;
      const lastReview = lastReviewStr ? new Date(lastReviewStr) : null;
      const oneYearAgo = new Date();
      oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);
      const reviewDue = !lastReview || lastReview < oneYearAgo;

      auditLog(req, "provider_share_summary_viewed", "PatientProfile", userId, {
        conditionsCount: conditions.length,
        surgeriesCount: surgeries.length,
        familyHistoryCount: familyHistory.length,
        pertinentPositivesCount: pertinentPositives.length,
      });

      res.json({
        patientName: [profile?.firstName, profile?.middleName !== "NMN" ? profile?.middleName : "", profile?.lastName].filter(Boolean).join(" "),
        dateOfBirth: profile?.dateOfBirth ? new Date(profile.dateOfBirth).toLocaleDateString("en-US") : "",
        gender: profile?.gender || "",
        preferredLanguage: profile?.preferredLanguage || "English",
        lastReviewDate: lastReview ? lastReview.toLocaleDateString("en-US") : "",
        conditions,
        surgeries,
        familyHistory,
        medications,
        allergies,
        lifestyle: {
          smoking: "",
          alcohol: "",
          exercise: (profile as any)?.preferredActivityLevel || "",
        },
        pertinentPositives: [...new Set(pertinentPositives)],
        reviewDue,
      });

    } catch (error) {
      console.error("Provider share summary error:", error);
      res.status(500).json({ error: "Failed to generate provider summary" });
    }
  });

