      const { title, description, category, targetValue, targetUnit, frequency, startDate, endDate, isAiSuggested, aiRationale, relatedConditions, reminderEnabled, reminderTime } = req.body as any;
      
      const goal = await storage.createHealthGoal({
        userId,
        title,
        description,
        category,
        targetValue,
        targetUnit,
        frequency: frequency || "daily",
        startDate: new Date(startDate || Date.now()),
        endDate: endDate ? new Date(endDate) : null,
        isAiSuggested: isAiSuggested || false,
        aiRationale,
        relatedConditions,
        status: "active",
        reminderEnabled: reminderEnabled !== false,
        reminderTime,
      });
      
      // Award points for creating first goal (check if this is their first)
      const userGoals = await storage.getHealthGoals(userId);
      if (userGoals.length === 1) {
        await storage.awardPoints(userId, 25, "first_goal_created", "milestones", "goal", goal.id);
      } else {
        await storage.awardPoints(userId, 10, "goal_created", "goals", "goal", goal.id);
      }
      
      auditLog(req, "health_goal_create", "health_goal", goal.id);
