  app.get("/api/health-graph/node/:nodeId", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const nodeId = (req.params as any).nodeId;
      const graph = healthGraphService.exportGraphForVisualization(userId);

      const node = graph.nodes.find((n: any) => n.id === nodeId);
      if (!node) return res.status(404).json({ error: "Node not found" });

      const connections = graph.links.filter(
        (l: any) => l.source === nodeId || l.target === nodeId
      );
      const connectedNodeIds = connections.map((c: any) =>
        c.source === nodeId ? c.target : c.source
      );
      const connectedNodes = graph.nodes.filter((n: any) =>
        connectedNodeIds.includes(n.id)
      );

      res.json({
        node,
        connections: connections.map((c: any) => ({
          ...c,
          connectedNode: connectedNodes.find(
            (n: any) => n.id === (c.source === nodeId ? c.target : c.source)
          ),
        })),
        totalConnections: connections.length,
      });
    } catch (error) {
      console.error("Node detail error:", error);
      res.status(500).json({ error: "Failed to get node details" });
    }
  });


