  // =============== AI NARRATIVE SUMMARIES ===============


  app.get("/api/care-summary/narrative", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const months = parseInt((req.query as any).months as string) || 6;
      const cutoff = new Date();
      cutoff.setMonth(cutoff.getMonth() - months);

      const records = await storage.getHealthRecords(userId);
      const recentRecords = records.filter(r => new Date(r.date) >= cutoff);

      const recordsByType: Record<string, any[]> = {};
      for (const r of recentRecords) {
        if (!recordsByType[r.type]) recordsByType[r.type] = [];
        recordsByType[r.type].push({ title: r.title, date: r.date, summary: r.summary, provider: r.provider });
      }

      const profile = await storage.getPatientProfile(userId);
      const patientContext = profile ? `Patient: ${profile.firstName || ""} ${profile.lastName || ""}, DOB: ${profile.dateOfBirth || "unknown"}` : "Patient profile not available";

      const dataSnapshot = Object.entries(recordsByType).map(([type, recs]) => {
        const items = recs.slice(0, 15).map(r => `- ${r.title} (${new Date(r.date).toLocaleDateString()}): ${r.summary || ""}`).join("\n");
        return `${type.toUpperCase()} (${recs.length} records):\n${items}`;
      }).join("\n\n");

      let narrative: string;
      try {
        const sanitizedContext = sanitizeHealthData(patientContext);
        const sanitizedSnapshot = sanitizeHealthData(dataSnapshot);
        const completion = await chatComplete({
          model: "deep",
          messages: [
            {
              role: "system",
              content: `You are a clinical documentation assistant creating patient-friendly care summaries. Generate a clear, chronological narrative summary of the patient's health journey. Use plain language, organize by time period, highlight key events, and note any patterns or trends. Do NOT diagnose or prescribe. Include sections: Overview, Key Events, Ongoing Management, and Notable Trends. Keep it under 800 words.`,
            },
            {
              role: "user",
              content: `Generate a ${months}-month care narrative summary for this patient.\n\n${sanitizedContext}\n\nHealth Records:\n${sanitizedSnapshot}`,
            },
          ],
          temperature: 0.3,
          maxOutputTokens: 1500,
          dataCategories: ["demographics", "conditions", "medications", "lab_results", "vitals", "clinical_notes"],
          purpose: "documentation",
          callerService: "routes",
          callerMethod: "narrativeSummary",
        });
        narrative = completion.content || "Unable to generate summary.";
      } catch {
        const typeCount = Object.entries(recordsByType).map(([t, r]) => `${r.length} ${t} records`).join(", ");
        narrative = `Care Summary (Last ${months} Months)\n\nDuring this period, ${recentRecords.length} health records were documented including ${typeCount}. ` +
          `Key events include: ${recentRecords.slice(0, 5).map(r => r.title).join(", ")}. ` +
          `Please consult your care team for a detailed review of your health journey.`;
      }

      auditLog(req, "narrative_summary_generated", "care_summary", userId, { months, recordCount: recentRecords.length });

      res.json({
        narrative,
        period: { months, from: cutoff.toISOString(), to: new Date().toISOString() },
        stats: {
          totalRecords: recentRecords.length,
          byType: Object.fromEntries(Object.entries(recordsByType).map(([k, v]) => [k, v.length])),
        },
        generatedAt: new Date().toISOString(),
      });
    } catch (error) {
      console.error("Narrative summary error:", error);
      res.status(500).json({ error: "Failed to generate narrative summary" });
    }
  });

