  // =============== ENHANCED FHIR BULK EXPORT ===============


  app.get("/api/fhir-bulk-export/one-click", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const records = await storage.getHealthRecords(userId);
      const profile = await storage.getPatientProfile(userId);

      const resourcesByType: Record<string, any[]> = {};

      const patientResource = {
        resourceType: "Patient",
        id: userId,
        name: [{ family: profile?.lastName || "", given: [profile?.firstName || ""].filter(Boolean) }],
        birthDate: profile?.dateOfBirth ? new Date(profile.dateOfBirth).toISOString().split("T")[0] : undefined,
        gender: profile?.gender || undefined,
        telecom: [
          profile?.phone ? { system: "phone", value: profile.phone } : null,
          profile?.email ? { system: "email", value: profile.email } : null,
        ].filter(Boolean),
        address: (profile as any)?.address ? [{ text: (profile as any).address }] : undefined,
      };
      resourcesByType["Patient"] = [patientResource];

      for (const record of records) {
        const fhirType = mapRecordTypeToFHIR(record.type);
        if (!resourcesByType[fhirType]) resourcesByType[fhirType] = [];

        const resource: any = {
          resourceType: fhirType,
          id: record.id,
          status: "final",
          subject: { reference: `Patient/${userId}` },
          code: { text: record.title },
          effectiveDateTime: new Date(record.date).toISOString(),
        };

        if (record.provider) resource.performer = [{ display: record.provider }];
        if (record.summary) resource.note = [{ text: record.summary }];
        if (record.details) resource.valueString = JSON.stringify(record.details);

        resourcesByType[fhirType].push(resource);
      }

      const ndjsonFiles: Record<string, string> = {};
      for (const [resourceType, resources] of Object.entries(resourcesByType)) {
        ndjsonFiles[resourceType] = resources.map(r => JSON.stringify(r)).join("\n");
      }

      auditLog(req, "fhir_bulk_export", "bulk_export", userId, {
        resourceTypes: Object.keys(ndjsonFiles),
        totalResources: records.length + 1,
      });

      res.json({
        exportId: `export_${Date.now()}`,
        format: "ndjson",
        files: ndjsonFiles,
        manifest: {
          transactionTime: new Date().toISOString(),
          request: `${req.protocol}://${req.get("host")}/api/fhir-bulk-export/one-click`,
          requiresAccessToken: true,
          output: Object.entries(ndjsonFiles).map(([type, content]) => ({
            type,
            url: `inline:${type}.ndjson`,
            count: content.split("\n").length,
          })),
        },
        stats: {
          totalResources: records.length + 1,
          byType: Object.fromEntries(Object.entries(resourcesByType).map(([k, v]) => [k, v.length])),
        },
      });
    } catch (error) {
      console.error("FHIR bulk export error:", error);
      res.status(500).json({ error: "Failed to export FHIR data" });
    }
  });


