  // =============== TREND SPARKLINE DATA ===============


  app.get("/api/health-records/:id/trend", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const recordId = (req.params as any).id;
      const record = await storage.getHealthRecord(recordId);
      if (!record || record.userId !== userId) return res.status(404).json({ error: "Record not found" });

      const records = await storage.getHealthRecords(userId);
      const similarRecords = records
        .filter(r => r.type === record.type && r.title === record.title)
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

      const trendData = similarRecords.map(r => {
        let value: number | null = null;
        if (r.details) {
          const details = r.details as Record<string, any>;
          const numericField = Object.keys(details).find(k => typeof details[k] === "number" || !isNaN(parseFloat(details[k])));
          if (numericField) value = parseFloat(details[numericField]);
        }
        return { date: r.date, value, id: r.id, title: r.title };
      }).filter(d => d.value !== null);

      const values = trendData.map(d => d.value as number);
      const trend = values.length >= 2
        ? (values[values.length - 1] > values[values.length - 2] ? "increasing" : values[values.length - 1] < values[values.length - 2] ? "decreasing" : "stable")
        : "insufficient_data";

      res.json({
        recordId,
        recordTitle: record.title,
        recordType: record.type,
        trendData,
        trend,
        stats: values.length > 0 ? {
          min: Math.min(...values),
          max: Math.max(...values),
          avg: Math.round(values.reduce((a, b) => a + b, 0) / values.length * 10) / 10,
          count: values.length,
          latest: values[values.length - 1],
        } : null,
      });
    } catch (error) {
      console.error("Trend data error:", error);
      res.status(500).json({ error: "Failed to get trend data" });
    }
  });

