  // Web patient-assistant chat — SSE endpoint consumed by ai-patient-assistant-chat.tsx.
  // Pipeline: scrubPHI(input) → chatComplete → scrubPHI(output) → Fable → guardrails → SSE burst.
  app.post("/api/patient-assistant/chat", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { userMessage, messages = [], contextControl } = req.body as {
        userMessage: string;
        messages?: { role: string; content: string }[];
        patientId?: string;
        contextControl?: { categories?: string[]; timeRange?: string; specificItems?: string[] };
      };

      if (!userMessage?.trim()) {
        return res.status(400).json({ error: "userMessage is required" });
      }

      // Stage 1 — scrub PHI from user input before any model call
      const { scrubbed: scrubbedUserMessage } = scrubPHI(userMessage);
      const scrubbedHistory = messages.map((m) => ({
        role: m.role as "user" | "assistant" | "system",
        content: scrubPHI(m.content).scrubbed,
      }));

      const systemPrompt =
        "You are a compassionate patient health assistant. Provide clear, accurate health information in plain language. " +
        "Always remind patients to consult their healthcare provider for medical decisions. " +
        (contextControl?.categories?.length
          ? `Focus on: ${contextControl.categories.join(", ")}. `
          : "") +
        "Do not include personally identifiable information in your responses.";

      const aiResponse = await chatComplete({
        messages: [
          { role: "system", content: systemPrompt },
          ...scrubbedHistory,
          { role: "user", content: scrubbedUserMessage },
        ],
        dataCategories: ["conditions", "medications", "lab_results"],
        purpose: "patient_education",
        callerService: "patient-assistant-chat",
        callerMethod: "chat",
      });

      const rawContent = aiResponse.content;

      // Stage 2 — scrub PHI from raw LLM output before downstream model call
      const { scrubbed: scrubbedRawContent } = scrubPHI(rawContent);

      // Stage 3 — Fable rewrite (PHI already scrubbed)
      let preGuardrailContent = scrubbedRawContent;
      try {
        const fableResult = await rewriteInFableStyle(scrubbedRawContent, userId);
        preGuardrailContent = fableResult.narrative;
      } catch {
        // Fall back to scrubbed output if Fable rewrite fails
      }

      // Stage 4 — guardrails are the final gate before delivery
      const guardrailResult = await runGuardrails(preGuardrailContent, {
        route: "/api/patient-assistant/chat",
        userId,
      });

      // Stream the fully-gated response back in the SSE format the web component expects
      res.setHeader("Content-Type", "text/event-stream");
      res.setHeader("Cache-Control", "no-cache");
      res.setHeader("Connection", "keep-alive");

      res.write(`data: ${JSON.stringify({ type: "content", content: guardrailResult.output })}\n\n`);
      res.write(`data: ${JSON.stringify({
        type: "metadata",
        suggestedFollowUps: [],
        relatedAppFeatures: [],
        medicalTermsExplained: {},
        includesDisclaimer: true,
        guardrails: {
          reviewRequired: guardrailResult.reviewRequired,
          reviewQueueId: guardrailResult.reviewQueueId,
          phiTokensReplaced: guardrailResult.phiTokensReplaced,
        },
      })}\n\n`);
      res.write(`data: ${JSON.stringify({ type: "done" })}\n\n`);
      res.end();
    } catch (error) {
      console.error("Patient assistant chat error:", error);
      if (!res.headersSent) {
        res.status(500).json({ error: "Failed to process message" });
      } else {
        res.write(`data: ${JSON.stringify({ type: "error", error: "Failed to process message" })}\n\n`);
        res.end();
      }
    }
  });

