  app.post("/api/ai-summary/patient/:patientId", requireAuth, requireFeature("ai_summaries"), authRoute(async (req, res, userId) => {
    try {
      const result = await generateDeduplicatedSummary((req.params as any).patientId, userId);

      // Stage 1 — scrub PHI from the raw summary before any downstream model call
      const { scrubbed: scrubbedSummary } = scrubPHI(result.summary);

      // Stage 2 — rewrite in Fable style; PHI already scrubbed
      let preGuardrailSummary = scrubbedSummary;
      try {
        const fableResult = await rewriteInFableStyle(scrubbedSummary, userId);
        preGuardrailSummary = fableResult.narrative;
      } catch {
        // Fall back to scrubbed summary if Fable rewrite fails
      }

      // Stage 2 — guardrails are the final gate before delivery;
      // when reviewRequired=true the output is the mandated hold message
      const guardrailResult = await runGuardrails(preGuardrailSummary, {
        route: "/api/ai-summary/patient",
        userId,
      });

      auditLog(req, "ai_summary_generate", "Patient", (req.params as any).patientId, { provider: result.provider, duplicatesRemoved: result.duplicatesRemoved });
      res.json(gatedSuccess({
        ...result,
        summary: guardrailResult.output,
        guardrails: {
          reviewRequired: guardrailResult.reviewRequired,
          phiTokensReplaced: guardrailResult.phiTokensReplaced,
        },
      }, userId));
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  }));


