      const existing = await storage.getAppointment(appointmentId);
      if (!existing || existing.userId !== userId) {
        return res.status(404).json({ error: "Appointment not found" });
      }
      
      const ALLOWED_APPOINTMENT_FIELDS = [
        'title', 'notes', 'status', 'scheduledAt', 'location',
        'providerName', 'appointmentType', 'reminderMinutes'
      ] as const;
      const updates: Record<string, unknown> = {};
      for (const field of ALLOWED_APPOINTMENT_FIELDS) {
        if (field in req.body) updates[field] = req.body[field];
      }
      if (updates.scheduledAt) {
        updates.scheduledAt = new Date(updates.scheduledAt as string);
      }

      const updated = await storage.updateAppointment(appointmentId, updates);
      auditLog(req, "update_appointment", "appointment", appointmentId);
      res.json(updated);
